(* [comment removed for export] *)
Lemma w4_blk_fold : forall (Q : machine_state -> Prop) (RNG : footprint) (mm : amem) (F : bvmap 5 word) (fc : bv 32)
    (r1 r3 r4 r5 r6 r7 r8 r9 r10 r11 r12 r13 r14 r15 r16 r17 r18 r19 r20 r21 r22 r23 r24 r25 r27 r28 r29 r30 r31 : word)
    (P B0 B1 B2 B3 DL : Z) (w88 w96 w104 w224 : word),
  W4C mm P w88 w96 w104 (Z_to_bv 64 B2) (Z_to_bv 64 B1) (Z_to_bv 64 B0) w224 (Z_to_bv 64 DL) ->
  mem_inv asegs mm -> rng RNG P 496 -> rng_aimg RNG -> 0x10007fff8000 <= P -> P + 496 <= 2^47 ->
  0 <= B0 -> 0 <= B1 -> 0 <= B2 -> 0 <= B3 -> 0 <= DL -> B0 + DL < 2^64 -> B1 + DL < 2^64 -> B2 + DL < 2^64 -> B3 + DL < 2^64 ->
  (forall mm', munch [(P + 88, P + 144); (P + 224, P + 240)] mm mm' -> wmono asegs mm mm' -> mem_inv asegs mm' ->
     W4C mm' P w88 w96 w104 (Z_to_bv 64 (B2 + DL)) (Z_to_bv 64 (B1 + DL)) (Z_to_bv 64 (B0 + DL)) w224 (Z_to_bv 64 DL) ->
     evtF asegs RNG Q (MS (mkR r1 (Z_to_bv 64 P) r3 r4 r5 r6 r7 r8 r9 (Z_to_bv 64 (B2 + DL)) (Z_to_bv 64 DL) r12 r13 r14 r15 r16 r17
                              r18 r19 r20 r21 r22 r23 r24 r25 (Z_to_bv 64 (B3 + DL)) r27 r28 r29 r30 r31)
                          F (Z_to_bv 64 0x8eef8) fc None mm' (seg_rom asegs))) ->
  evtF asegs RNG Q (MS (mkR r1 (Z_to_bv 64 P) r3 r4 r5 r6 r7 r8 r9 r10 r11 r12 r13 r14 r15 r16 r17 r18 r19 r20 r21
